function refreshGlobalBar(){const total=clientsState.items.filter(c=>!c.archived&&pipelineStageOf(c)==='Fechado').reduce((n,c)=>n+(Number(c.monthly)||0),0),target=Number(dashState.target)||10000;document.querySelector('#global-revenue').textContent=money(total);document.querySelector('#global-target').textContent=money(target);document.querySelector('.global-goal').style.setProperty('--goal-percent',Math.min(100,Math.round(total/target*100))+'%')}
function globalDialog(title,content){document.querySelector('.global-dialog')?.remove();const el=document.createElement('div');el.className='global-dialog';el.innerHTML=`<div role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${content}<button data-global="close">Fechar</button></div>`;document.body.append(el);el.querySelector('input')?.focus()}
function globalSearch(q){const list=document.querySelector('#global-search-results');if(!list)return;const term=q.trim().toLocaleLowerCase('pt-BR');const matches=term?clientsState.items.filter(c=>[c.name,c.email,c.phone,c.project].some(v=>String(v||'').toLocaleLowerCase('pt-BR').includes(term))).slice(0,12):[];list.innerHTML=matches.length?matches.map(c=>`<button class="global-result" data-global="client" data-id="${esc(c.id)}">${esc(c.name)}<small>${esc(c.project||'Sem projeto')} · ${esc(c.email||'Sem e-mail')}</small></button>`).join(''):'<p>Digite para buscar clientes e projetos.</p>'}
document.addEventListener('click',e=>{const b=e.target.closest('[data-global]');if(!b){if(e.target.classList.contains('global-dialog'))e.target.remove();return}const action=b.dataset.global;if(action==='close'){document.querySelector('.global-dialog')?.remove();return}if(action==='client'){document.querySelector('.global-dialog')?.remove();menu.querySelector('[data-page="Clientes"]').click();openModal('details',b.dataset.id);return}if(action==='search'){globalDialog('Buscar no CRM','<input id="global-search" type="search" placeholder="Buscar cliente, e-mail, telefone ou projeto..." aria-label="Buscar no CRM"><div id="global-search-results"></div>');return}if(action==='goal'){menu.querySelector('[data-page="Dashboard"]').click();return}if(action==='visibility'){document.body.classList.toggle('global-hidden-values');b.setAttribute('aria-label',document.body.classList.contains('global-hidden-values')?'Mostrar valores':'Ocultar valores');return}if(action==='tasks'){menu.querySelector('[data-page="Kanban"]').click();return}if(action==='files'){menu.querySelector('[data-page="Clientes"]').click();toast('Abra um cliente e selecione a aba Arquivos.');return}if(action==='theme'){globalDialog('Aparência','<p>O visual Doctype está ativo. A personalização de tema será configurada no perfil.</p>');return}if(action==='language'){globalDialog('Idioma','<p>Português (Brasil) é o idioma disponível nesta versão.</p>');return}if(action==='support'){globalDialog('Ajuda','<p>Use Clientes para abrir os cadastros, Pipelines para acompanhar negociações e Operacional para tarefas.</p>');return}if(action==='notifications'){globalDialog('Notificações','<p>Nenhuma notificação nova nesta sessão.</p>');return}if(action==='credits'){globalDialog('Créditos','<p>A integração de créditos e agentes IA ainda não está conectada. Consulte esta área quando a integração estiver disponível.</p>');return}if(action==='account'){globalDialog('Conta Doctype','<p>DOC.FREELA · versão de demonstração. Configurações de conta e assinatura ainda não estão conectadas.</p>')}});
document.addEventListener('input',e=>{if(e.target.id==='global-search')globalSearch(e.target.value)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.global-dialog')?.remove();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('[data-global=search]')?.click()}});
refreshGlobalBar();document.addEventListener('click',()=>setTimeout(refreshGlobalBar,0));document.addEventListener('submit',()=>setTimeout(refreshGlobalBar,0));
